  useEffect(() => {
    if (!deadlineLive) console.error("[TEMPORAL] expired deadline suppressed on success page", { product: "rental-property-deduction-audit", deadlineIso: "2026-10-31T23:59:59.000+11:00" });
  }, []);

  async function init() {
    const params    = new URLSearchParams(window.location.search);
    const sessionId = params.get("session_id");
    let name = "there";
    if (sessionId) {
      try {
        const r = await fetch(`/api/get-session?id=${sessionId}`);
        const d = await r.json();
        if (d.firstName) { name = d.firstName; setFirstName(d.firstName); }
      } catch { /* non-fatal */ }
    }
    await generateAssessment(name);
  }

  async function generateAssessment(name: string) {
    setLoading(true);
    setError("");
    const params    = new URLSearchParams(window.location.search);
    const sessionId = params.get("session_id");

    try {
      // ── STEP 1: Try fetching pre-generated assessment from Supabase ──
      // Generated by webhook at purchase time — instant load, no API call
      if (sessionId) {
        const r = await fetch(`/api/get-assessment?session_id=${sessionId}`);
        if (r.ok) {
          const d = await r.json();
          if (d.assessment) {
            // D — NAME FALLBACK. The greeting is read from /api/get-session, which returns
            // "there" whenever the Stripe session carries no customer_details.name (or the
            // retrieve throws). The stored row already holds the buyer name and
            // /api/get-assessment already returns it as customerName — the page simply never
            // looked. Measured on a live 2026-09-17 beckham row that rendered "What this
            // means for you" while the row itself was not anonymous. Only fills the gap; a
            // name that DID arrive from get-session always wins, and the value goes through
            // the same trim/capitalise as any other.
            if (name === "there" && typeof d.customerName === "string" && d.customerName.trim() !== "") {
              setFirstName(d.customerName);
            }
            setAssessment(d.assessment);
            // FREEZE: adopt the stored document verbatim when it exists.
            if (hasFrozenPack(d.assessment)) {
              setPack((d.assessment as Record<string, unknown>).rendered as RenderedPack);
            } else {
              // HEAL ON VIEW — a row written before the freeze. Render it exactly as the
              // writer would have, show that, and post it so the SECOND view reads a frozen
              // copy. Keyed on the row's OWN product id (the identity the webhook stored it
              // under) so a heal can never re-key a row; the constant is only a fallback.
              const healId = typeof d.productId === "string" && d.productId ? d.productId : PRODUCT_REGISTRY_ID;
              const healed = renderPack(d.assessment as Record<string, unknown>, {
                productId:    healId,
                tier:         TIER,
                customerName: typeof d.customerName === "string" ? d.customerName : name,
                fieldList:    getAssessmentFields(healId, TIER),
              });
              setPack(healed);
              if (sessionId && !frozePosted.current) {
                frozePosted.current = true;
                fetch("/api/freeze-pack", {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({ session_id: sessionId, rendered: healed }),
                }).catch(() => { /* non-fatal: the buyer already has their pack on screen */ });
              }
            }
            setLoading(false);
            return;
          }
        }
      }

      // ── STEP 2: Fallback — generate now via /api/assess ──────────────
      // Runs if webhook hasn't stored assessment yet (e.g. timing, retry)
      // Bind to the user's REAL engine answers — the keys EngineCalculator actually wrote,
      // which are keyed by the ROUTE TAIL (engineSessionKey), NOT by config.id: the two differ
      // on day-183-rule and spain-beckham, and passing config.id missed every read (DECISION-A).
      // (<slug-tail>_answers + <slug-tail>_qualification) — via the SAME composer the webhook uses
      // (F5 contract). The legacy per-field keys are never written by an engine-native
      // calculator, so reading them would always fall back to defaults → a generic,
      // corpus-contradicting assessment.
      const inputs = buildComposerInputsFromSession("rental-property-deduction-audit");

      const res = await fetch("/api/assess", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          product_id: "rental-property-deduction-audit",
          market:     "Australia",
          authority:  "ATO",
          tier:       2,
          name: name === "there" ? "" : name,
          inputs,
          fields: ["deductionStatus","expenseClassification","initialRepairRisk","overclaims","missedDeductions","capitalWorksAnalysis","depreciationOpportunity","recordQualityAssessment","evidenceRegister","multiYearDeductionPlan","auditRiskRating","strongestRiskTrigger"],
        }),
      });
      const data = await res.json();
      if (!res.ok || data.error) throw new Error(data.error || "Assessment failed");
      setAssessment(data.assessment);
      // FREEZE, fallback path. /api/assess is a pure wrapper and has never written to the
      // database, so a fallback-generated pack previously had NO persistence at all — the
      // buyer re-derived it on every visit. Render it once, show that, and post it through
      // the same write-once route the heal path uses.
      {
        const composed = renderPack(data.assessment as Record<string, unknown>, {
          productId:    PRODUCT_REGISTRY_ID,
          tier:         TIER,
          customerName: name === "there" ? "" : name,
          fieldList:    getAssessmentFields(PRODUCT_REGISTRY_ID, TIER),
        });
        setPack(composed);
        if (sessionId && !frozePosted.current) {
          frozePosted.current = true;
          fetch("/api/freeze-pack", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ session_id: sessionId, rendered: composed }),
          }).catch(() => { /* non-fatal */ });
        }
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to generate assessment");
      // Graceful fallback — page still shows files and calendar
      const placeholder = {
        deductionStatus: "Your personalised deductionStatus is being prepared — please refresh in a moment.",
        expenseClassification: "Your personalised expenseClassification is being prepared — please refresh in a moment.",
        initialRepairRisk: "Your personalised initialRepairRisk is being prepared — please refresh in a moment.",
        overclaims: "Your personalised overclaims is being prepared — please refresh in a moment.",
        missedDeductions: "Your personalised missedDeductions is being prepared — please refresh in a moment.",
        capitalWorksAnalysis: "Your personalised capitalWorksAnalysis is being prepared — please refresh in a moment.",
        depreciationOpportunity: "Your personalised depreciationOpportunity is being prepared — please refresh in a moment.",
        recordQualityAssessment: "Your personalised recordQualityAssessment is being prepared — please refresh in a moment.",
        evidenceRegister: "Your personalised evidenceRegister is being prepared — please refresh in a moment.",
        multiYearDeductionPlan: "Your personalised multiYearDeductionPlan is being prepared — please refresh in a moment.",
        auditRiskRating: "Your personalised auditRiskRating is being prepared — please refresh in a moment.",
        strongestRiskTrigger: "Your personalised strongestRiskTrigger is being prepared — please refresh in a moment.",
        accountantQuestions: [
          "What is my exact ATO position based on my answers?",
          "What is the single most important action I should take before 31 October 2026 (a Saturday — lodge by Monday 2 November 2026)?",
          "Are there any planning opportunities specific to my situation?",
        ],
        actions: [],
      } as unknown as Assessment;
      setAssessment(placeholder);
      // FREEZE — the reader is pack-only, so the graceful fallback must produce a PACK too,
      // or an /api/assess failure would render an empty body instead of the holding copy.
      // NOT posted to /api/freeze-pack: this is placeholder text, and freezing it would
      // permanently store "is being prepared" as the buyer's document.
      setPack(renderPack(placeholder as Record<string, unknown>, {
        productId:    PRODUCT_REGISTRY_ID,
        tier:         TIER,
        customerName: name === "there" ? "" : name,
        fieldList:    getAssessmentFields(PRODUCT_REGISTRY_ID, TIER),
      }));
    } finally {
      setLoading(false);
    }
  }

  function handleCalendar() {
    const now = new Date().toISOString().replace(/[-:]/g,"").split(".")[0] + "Z";
    function relativeDate(d: number): string {
      return new Date(Date.now() + d * 86400000).toISOString().split("T")[0].replace(/-/g,"");
    }
    const ics = [
      "BEGIN:VCALENDAR","VERSION:2.0",
      "PRODID:-//TaxCheckNow//COLE//EN",
      "CALSCALE:GREGORIAN","METHOD:PUBLISH",
      `X-WR-CALNAME:Rental Property Deduction Audit — Deadlines`,
      "BEGIN:VEVENT",
      `UID:rda-review-${Date.now()}@taxchecknow.com`,
      `DTSTART;VALUE=DATE:${relativeDate(14)}`,
      `DTEND;VALUE=DATE:${relativeDate(14)}`,
      `DTSTAMP:${now}`,
      "SUMMARY:Rental — Annual deduction review",
      "DESCRIPTION:Review all rental expenses and classify capital vs repairs before lodging return.",
      "STATUS:CONFIRMED",
      "END:VEVENT",
      "BEGIN:VEVENT",
      `UID:rda-return-${Date.now()}@taxchecknow.com`,
      `DTSTART;VALUE=DATE:${"20261031"}`,
      `DTEND;VALUE=DATE:${"20261031"}`,
      `DTSTAMP:${now}`,
      "SUMMARY:Tax Return Due",
      "DESCRIPTION:Lodge individual return with rental schedule.",
      "STATUS:CONFIRMED",
      "END:VEVENT",
      "END:VCALENDAR",
    ].join("\r\n");
    const blob = new Blob([ics], { type: "text/calendar;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = "rental-property-deduction-audit.ics";
    document.body.appendChild(a); a.click();
    document.body.removeChild(a); URL.revokeObjectURL(url);
    setCalDone(true);
  }

